// --- GENUS-2 SURFACE (widened holes) ---
// Uses the smooth blend (smooth min) of two tori.

// 1. Parameters wired to your sliders (A, B, C)
float rMain = A > 0.0 ? A : 0.8;        // Main ring radius
// DEFAULTS CHANGED BELOW:
float rTube = B > 0.0 ? B : 0.12;       // Reduced tube thickness (was 0.25)
float smoothFactor = C > 0.0 ? C : 0.2; // Less invasive blend (was 0.4)

// 2. Automatic animation wired to time 't'
// Makes the gap between the two holes "breathe" over time
float offset = 0.8 + 0.2 * sin(t * 2.0); 

// 3. Compute the coordinates of the two tori translated along the X axis
vec3 p1 = p - vec3(-offset, 3.0*sin(t), 0.0);
vec3 p2 = p - vec3(offset, 0.0, 0.0);

// 4. Exact SDFs (Signed Distance Function) for the two tori
float d1 = length(vec2(length(p1.xy) - rMain, p1.z)) - rTube;
float d2 = length(vec2(length(p2.xy) - rMain, p2.z)) - rTube;

// 5. Smooth Minimum: the magic that merges the two shapes like water drops
float h = clamp(0.5 + 0.5 * (d2 - d1) / smoothFactor, 0.0, 1.0);
float finalDistance = mix(d2, d1, h) - smoothFactor * h * (1.0 - h);

return finalDistance;
